import React from "react";
import { Link } from "react-router-dom";
import Header from "../atoms/Header/Header";
import ProjectCard from "../atoms/ProjectCard/ProjectCard";
import WordFlip from "../atoms/WordFlip/WordFlip";
import Skills from "../atoms/Skills/Skills";
import "./Home.css";
import Capability from "../atoms/Capability/Capability";
import MailLogo from "../../assets/svg/mail.svg";
import LinkedInLogo from "../../assets/svg/linkedin.svg";
import GithubLogo from "../../assets/svg/github.svg";
import FacebookLogo from "../../assets/svg/facebook.svg";
// import doc from "../../assets/doc.pdf";

function Home() {
  return (
    <div className="home">
      <Header />
      <WordFlip />
      <div className="home__projects" id="projects">
        <div className="home__projects--title">PROJECTS</div>
        {/* <div className="title">PROJECTS</div> */}
        <div className="home__projects--row">
          {/* <div className="home__projects--row--title">PROJECTS</div> */}
          <ProjectCard
            title="LORA"
            body="An e-learning web app to create learning objectives, materials and assessments"
            stack="React, Express JS, Neo4J"
            customStyle={{ marginBottom: "1.8rem" }}
            blocked
          />
          <ProjectCard
            title="PeoPulz"
            body="A one stop app for clinical customers to access their clinical records"
            stack="React-Native, AWS Amplify, AWS API"
            blocked
          />
          <ProjectCard
            title="PetPulz"
            body="An app to book appointments with registered veterinaries and access registered pets information"
            stack="React-Native, AWS Amplify, AWS API"
            blocked
          />
          <ProjectCard
            title="Online Fashion Store"
            body="An ecommerce web app with an admin dashboard, user and product management"
            stack="React JS, Express JS, MongoDB"
            githubLink="https://github.com/SLIIT-AF/3rd-Yr-1st-Sem---OnlineShoppingCartSystem---FashionStore"
          />
          <ProjectCard
            title="Driving Exam App"
            body="A mobile app to assist candidates taking the Sri 
            Lankan driving exam written test"
            stack="Dart, Flutter"
            githubLink="https://github.com/adheebshafik/Srilanka_Driving_Exam_App"
            customStyle={{ marginBottom: "1.8rem" }}
          />
          <ProjectCard
            title="POS Sytem"
            body="A complete POS system with billing, inventory and employee management"
            stack="Java Swing, MySQL, XAMPP"
            githubLink="https://github.com/adheebshafik/Point-of-Sales-System"
          />
          <ProjectCard
            title="RepairIt App"
            body="A platform to register vehicles, upload photos, get quotations and book inspection appointments"
            stack="Java, Firebase Real-Time DB"
            githubLink="https://github.com/adheebshafik/RepairIt"
          />
          <ProjectCard
            title="Timetable Generator"
            body="A desktop app to generate timetables based on constraints and preferences"
            stack="React, SQLite, ElectronJS"
            customStyle={{ marginBottom: "1.8rem" }}
            blocked
          />
        </div>
      </div>

      <div class="custom-shape-divider-top-1641451071">
        <svg
          data-name="Layer 1"
          xmlns="http://www.w3.org/2000/svg"
          viewBox="0 0 1200 120"
          preserveAspectRatio="none">
          <path
            d="M1200 120L0 16.48 0 0 1200 0 1200 120z"
            class="shape-fill"></path>
        </svg>
      </div>

      <div className="home__skills" id="skills">
        <Skills />
      </div>

      <div className="home__capabilities">
        <Capability />
      </div>
      {/*  */}
      <div className="home__about" id="aboutme">
        <span className="home__about--name">ADHEEB SHAFIK</span>
        <span className="home__about--about">ABOUT ME</span>
        <p>
          {/* Lorem ipsum dolor sit, amet consectetur adipisicing elit. Quae fugiat,
          et vitae aspernatur qui nemo sapiente sunt expedita ducimus eum iste
          consectetur perspiciatis atque labore natus, facere ex voluptas cum
         rem officia, minus earum ab harum! */}
          Hi, I'm Adheeb - a passionate full-stack developer with a sharp eye for detail and a constant drive to learn and adapt to new tools and technologies.
          I enjoy building robust, user-friendly applications from end to end.
        </p>
        {/* <a
          className="home__about--button"
          href={doc}
          download={"adheebshafik_cv.pdf"}>
          DOWNLOAD CV
        </a> */}
      </div>
      {/*  */}

      <div class="custom-shape-divider-bottom-1641707663">
        <svg
          data-name="Layer 1"
          xmlns="http://www.w3.org/2000/svg"
          viewBox="0 0 1200 120"
          preserveAspectRatio="none">
          <path
            d="M1200 120L0 16.48 0 0 1200 0 1200 120z"
            class="shape-fill"></path>
        </svg>
      </div>

      <footer className="home__footer" id="contact">
        <div className="home__footer--socials">
          <a href="mailto:adheebshafik@gmail.com">
            <img src={MailLogo} className="home__footer--socials--img" />
            <div className="home__footer--socials--text">Email Me</div>
          </a>
          <img
            src={LinkedInLogo}
            onClick={() =>
              window.open("https://www.linkedin.com/in/adheebshafik/")
            }
          />
          <div className="home__footer--socials--text">Connect With Me</div>
          <img
            src={GithubLogo}
            onClick={() => window.open("https://github.com/adheebshafik")}
          />
          <div className="home__footer--socials--text">Follow Me</div>
          {/*<img*/}
          {/*  src={FacebookLogo}*/}
          {/*  onClick={() => window.open("https://www.facebook.com/adheebshafik")}*/}
          {/*/>*/}
          <div className="home__footer--socials--text">Get In Touch</div>
        </div>
        <div className="home__footer--signoff">© 2025 - Adheeb Shafik</div>
      </footer>
    </div>
  );
}

export default Home;
