import React from "react";
import "./ProjectCard.css";
import Logo from "../../../assets/img/github.svg";

import BGIMG from "../../../assets/img/cardBG.webp";

function ProjectCard({
  title,
  body,
  stack,
  githubLink,
  customStyle,
  blocked,
  CardImg,
}) {
  return (
    <div
      className={`projectCard ${blocked && "blocked"}`}
      style={{
        backgroundImage: `url(${BGIMG})`,
      }}>
      <div className="projectCard__cardContent">
        <h2 className="projectCard__title">{title}</h2>
        <div className="projectCard__body">{body}</div>
        <div className="projectCard__techStack" style={customStyle}>
          <span className="projectCard__techStack--left">Tech Stack</span>
          <span className="projectCard__techStack--right">{stack}</span>
        </div>
        <div
          className="projectCard__button"
          onClick={() => {
            if (blocked) return false;
            else window.open(githubLink);
          }}>
          <img src={Logo} />
          <span>Github</span>
        </div>
      </div>
    </div>
  );
}

export default ProjectCard;

ProjectCard.defaultProps = {
  title: "SL Driving Exam App",
  body: "A mobile app to assist candidates who are taking the Sri Lankan driving exam written test",
  stack: "Dart, Flutter",
  githubLink: "https://github.com/adheebshafik",
  CardImg: BGIMG,
};
